# -*- coding: utf-8 -*-
# Обновление системного промта kip8test до post-Task 330
# (шапка шахматки сине-серая; мелкий шрифт описаний кодов в попапе;
#  светлая тема — весь текст окон бара чёрный)
with open('Системный_промт_для_приложения_КИПиА.md', encoding='utf-8') as f:
    lines = f.readlines()

new3 = '''> **Версия документа:** 2026-09-06 (post-Task 330: ШАПКА ШАХМАТКИ СИНЕ-СЕРАЯ + МЕЛКИЙ ШРИФТ ОПИСАНИЙ КОДОВ + ЧЁРНЫЙ ТЕКСТ ОКОН БАРА В СВЕТЛОЙ ТЕМЕ [заявка: «Фон шапки шахматки табеля с кнопкой "Сотрудник +" и днями недель сделай темнее, ближе к сине-серому цвету. В окне выбора кодов ячеек, шрифт текста описания кодов сделай маленьким. В светлой теме, весь текст в окнах мероприятий и норм времени, в баре табеля, должен быть чёрным цветом.»]: 1) ШАПКА: тёмная — почти чёрная «морская» синева var(--bg-tertiary,#0e1621) → стальной сине-серый сланец #1e293b [.ws-grid thead th, th дней и th «Сотрудник +», непрозрачный — sticky]; hover заголовка «Сотрудник +» #15202f → #2a3a4c [светлее новой шапки, прежняя логика «hover светлее фона»]; СВЕТЛАЯ — прежде почти белая (240,240,240, сливалась с ФИО/ячейками #eef0f2) → #bfcad5 ОТДЕЛЬНЫМ правилом [из группового правила 240,240,240 шапка ИСКЛЮЧЕНА; селекты/колонка ФИО тела не тронуты]; градиенты подсветок столбцов (сегодня/hover/выбор, Tasks 313/316) — background-image ПОВЕРХ нового фона. 2) ПОПАП КОДОВ: #wsCellPopup .ws-popup-name — font-size 12px → 10px [line-height 1.35→1.3, перенос Task 319 сохранён]; код 13px bold и заголовок 11px НЕ тронуты; правило scoped под #wsCellPopup [окно «Мероприятия в этот день» и карточка — прежний размер]. 3) СВЕТЛАЯ ТЕМА, ОКНА БАРА — ВЕСЬ ТЕКСТ #000: мероприятия [.ws-ep-cap #1d7a37→#000; .ws-ep-item #666→#000; .ws-ep-text/.ws-ep-date #333→#000; «нет мероприятий» #wsEventsPanel .ws-cp-empty #999→#000]; нормы/праздники [.ws-cp-col #666→#000; .ws-cp-item b #333→#000; .ws-cp-empty/.ws-cp-legend #999→#000; плашки .ws-cp-norms>.ws-cp-cap #1d5f96→#000 и .ws-cp-days>.ws-cp-cap #b02c2c→#000; бейдж «предварительно» .ws-cal-prelim #a06b00→#000 (позднее правило-переопределение); чипы .ws-cp-day (k-hol #ff6b6b и др.) → #000 — правило ПОСЛЕ k-*, специфичность (0,2,0) равная, побеждает позднее]; ЦВЕТНЫЕ ПОДЛОЖКИ плашек/чипов/бейджа СОХРАНЕНЫ [смысловые фоны]; тёмная тема окон НЕ тронута. Тесты 1996→2010/0 [+14 test-task330.js; актуализированы work-schedule/313/318/319; SW v568→v569 в 30 файлах, «лишний инкремент»→v570]; browser task330-browser-check.py 27/27 [десктоп тёмн./светлая/мобайл 375: шапка #1e293b/#bfcad5, hover #2a3a4c, ФИО тела прежнее, описания 10px, чёрный текст окон (чипы legalic-моком), 0 JS-ошибок]; регресс 327 30/30, 328 36/36, 329 43/43; VLM ×3. ДЕПЛОЙ: ТОЛЬКО Pages + Ctrl+Shift+R ×1–2 — Apps Script/листы НЕ трогать. ПЕРЕНОС в kip8: НЕ выполнен — Tasks 315–330 одной партией [k8 v417→v418; в партии серверная часть Task 318 — .gs в Apps Script УЖЕ развёрнут (общий бэкенд), в kip8 синхронизировать файлы .gs])
'''

assert lines[2].startswith('> **Версия документа:**')
lines.insert(2, new3 if new3.endswith('\n') else new3 + '\n')
print('Строка 3 вставлена (цепочка версий)')

src = ''.join(lines)

reps = [
    ('> **Текущая версия кэша:** `kipia-test-v568`',
     '> **Текущая версия кэша:** `kipia-test-v569`'),
    ('| `kip8test` | PWA | `kipia-test-v568` |',
     '| `kip8test` | PWA | `kipia-test-v569` |'),
]
for old, new in reps:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Версии кэша обновлены (2 замены)')

reps2 = [
    ('├── tests/                      # 1996 юнит-тестов (Node.js, 47 файлов): run-all.js, test-role-access.js, и др.',
     '├── tests/                      # 2010 юнит-тестов (Node.js, 48 файлов): run-all.js, test-role-access.js, и др.'),
    ('ожидается `1996 passed, 0 failed`', 'ожидается `2010 passed, 0 failed`'),
    ('# Ожидается: 1996 passed, 0 failed', '# Ожидается: 2010 passed, 0 failed'),
]
for old, new in reps2:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Счётчики тестов обновлены (3 замены)')

# Буллет Task 330 — сразу ПОСЛЕ буллета Task 329
entry = ('\n- **Task 330 — ШАПКА ШАХМАТКИ СИНЕ-СЕРАЯ, МЕЛКИЙ ШРИФТ ОПИСАНИЙ КОДОВ, ЧЁРНЫЙ ТЕКСТ ОКОН БАРА (СВЕТЛАЯ ТЕМА)**: заявка: «Фон шапки шахматки табеля с кнопкой "Сотрудник +" и днями недель сделай темнее, ближе к сине-серому цвету. В окне выбора кодов ячеек, шрифт текста описания кодов сделай маленьким. В светлой теме, весь текст в окнах мероприятий и норм времени, в баре табеля, должен быть чёрным цветом.» 1) ФОН ШАПКИ ШАХМАТКИ (строка «Сотрудник +» + числа/дни недель, .ws-grid thead th — th дней И th ФИО одинаковые): ТЁМНАЯ — var(--bg-tertiary, #0e1621) (почти чёрная «морская» синева, шапка сливалась с колонкой ФИО и фоном страницы) → стальной СИНЕ-СЕРЫЙ сланец #1e293b [непрозрачный — шапка sticky; плотная «крыша», отделена от тулбара #17212b и от ФИО тела #0e1621]; hover заголовка «Сотрудник +» (.ws-emp-head-add:hover) #15202f → #2a3a4c [светлее новой шапки — прежняя логика «hover светлее фона»; светлая тема hover #e2e8ef не менялась — светлее #bfcad5]; СВЕТЛАЯ — rgba(240,240,240,0.95) (почти белая, шапка СЛИВАЛАСЬ с колонкой ФИО и пустыми ячейками #eef0f2 — VLM подтвердил «сливается с фоном») → сине-серый #bfcad5 ОТДЕЛЬНЫМ ПРАВИЛОМ [data-theme="light"] .ws-grid thead th [из группового правила 240,240,240 (селекты месяца/года + колонка ФИО тела) шапка ИСКЛЮЧЕНА — остальные элементы группы НЕ тронуты]; подсветки столбцов шапки (ws-today-col/ws-hover-col/ws-sel-col, Tasks 313/316) — background-image-градиенты ПОВЕРХ нового background-color, НЕ затронуты. 2) ОКНО ВЫБОРА КОДОВ ЯЧЕЕК — ШРИФТ ОПИСАНИЙ МАЛЕНЬКИЙ: #wsCellPopup .ws-popup-name font-size 12px → 10px [Task 319 «чуть мельче» 13→12; Task 330 «маленький» 12→10; line-height 1.35→1.3; white-space normal/overflow-wrap break-word — перенос длинных названий сохранён]; сам КОД (.ws-popup-code 13px bold Consolas) и заголовок окна (.ws-popup-title 11px) НЕ тронуты; правило по-прежнему ТОЛЬКО под #wsCellPopup — окно «Мероприятия в этот день» (#wsEventsPopup) и попап карточки сотрудника — прежний однострочный вид. 3) СВЕТЛАЯ ТЕМА — ВЕСЬ ТЕКСТ ОКОН «МЕРОПРИЯТИЯ» (#wsEventsPanel) И «НОРМА/ПРАЗДНИКИ» (#wsCalPanel) БАРА ТАБЕЛЯ — ЧЁРНЫЙ #000: окно мероприятий [.ws-ep-cap (заголовок-плашка, прежде зелёный #1d7a37); .ws-ep-item (строки, #666); .ws-ep-date/.ws-ep-text (даты/текст, #333); «нет мероприятий…» (#wsEventsPanel .ws-cp-empty, #999)]; окно норм [.ws-cp-col (столбики, #666); .ws-cp-item b (значения, #333); .ws-cp-empty/.ws-cp-legend («нет…»/легенда, #999); плашки-заголовки .ws-cp-norms > .ws-cp-cap (прежде синий #1d5f96) и .ws-cp-days > .ws-cp-cap (прежде красный #b02c2c); бейдж «предварительно» .ws-cal-prelim (#a06b00 — перекрыт НОВЫМ поздним правилом Task 330 #000, прежнее правило живо для фона); чипы особых дней .ws-cp-day (k-hol #ff6b6b/k-reg #ffc107/k-tr #6aa6e0/k-sh #4ac771/k-wk #b0bec5 — правило [data-theme="light"] .ws-cp-day { color:#000 } ПОСЛЕ k-правил, специфичность (0,2,0) равная, побеждает позднее в исходнике)]; ЦВЕТНЫЕ ПОДЛОЖКИ СОХРАНЕНЫ [плашки/чипы/бейдж — смысловые фоны rgba-тинты, цвет остаётся ТОЛЬКО фоном]; ТЁМНАЯ тема окон бара НЕ тронута (заявка — только светлая). Верификация: сьют 1996→2010/0 (+14 tests/test-task330.js [CSS: thead #1e293b/#bfcad5, hover #2a3a4c, шапка вне группы 240,240,240, today/hover-градиенты живы; #wsCellPopup .ws-popup-name 10px scoped; светлая: ep-cap/item/text/date/empty, cp-col/item b/empty/legend, плашки, prelim (второе правило), чипы ПОСЛЕ k-hol, подложки живы, тёмная не тронута; SW v569/v570-guard]; актуализированы test-work-schedule [плашки светлой — #000], test-task313 [фон th #1e293b], test-task318 [hover #2a3a4c], test-task319 [.ws-popup-name 10px]; SW-бамп v568→v569 в 30 файлах, assertFalse «лишний инкремент» → v570 в 12 файлах); браузер task330-browser-check.py 27/27 (порт 8960, 3 контекста: десктоп 1280 ТЁМНАЯ [шапка rgb(30,41,59) в th дней и th «Сотрудник +», ФИО тела прежнее rgb(14,22,33), hover rgb(42,58,76), попап: .ws-popup-name 10px/код 13px/заголовок 11px; 0 JS-ошибок]; СВЕТЛАЯ [шапка rgb(191,202,213), ФИО rgba(240,240,240,0.95); мероприятия: cap rgb(0,0,0)+зелёная подложка, item/date/text rgb(0,0,0); нормы: cp-col/item b/плашки/легенда rgb(0,0,0); ЧИПЫ (мок legalic: праздник 8-го/перенос 9-го/сокращённый 10-го) — rgb(0,0,0) + подложки цветные; попап 10px; 0 JS-ошибок]; мобайл 375 светлая [шапка #bfcad5, описания 10px; 0 ошибок]); регресс task327 30/30, task328 36/36, task329 43/43 (шторка/шеврон/дни — не задеты); VLM ×3 (тёмная/светлая/кроп попапа: шапка сине-серая и выделяется, текст окон чёрный, описание мельче кода и читаем, дефектов нет); пруфы task330-proof-{dark,light,mobile}.png. ⚠️ ДЕПЛОЙ: ТОЛЬКО GitHub Pages + Ctrl+Shift+R ×1–2 (SW kipia-test-v568→v569) — Apps Script/листы НЕ трогать (только клиент) — см. scripts/DEPLOY-Task330-header-gray-smallfont-blacktext.md.')
lines2 = src.split('\n')
insert_at = None
for i, l in enumerate(lines2):
    if l.startswith('- **Task 329 —'):
        insert_at = i + 1
        break
assert insert_at is not None, 'буллет Task 329 не найден'
lines2.insert(insert_at, entry)
src = '\n'.join(lines2)
print('Буллет Task 330 вставлен (после Task 329)')

with open('Системный_промт_для_приложения_КИПиА.md', 'w', encoding='utf-8') as f:
    f.write(src)
print('Готово: Системный_промт_для_приложения_КИПиА.md → post-Task 330')
